package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;
import java.util.List;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ZipArchiveEntry#isUnixSymlink
 */
public class ZipArchiveEntry_isUnixSymlink_TriageGen2Test {

    /**
     * Test case: When the Unix mode contains the LINK_FLAG.
     * This should return true.
     */
    @Test
    public void testIsUnixSymlink_ReturnsTrueWhenModeIsLink() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_link");
        // Setting mode to exactly UnixStat.LINK_FLAG
        entry.setUnixMode(UnixStat.LINK_FLAG);

        assertTrue("isUnixSymlink should return true when mode matches LINK_FLAG", entry.isUnixSymlink());
    }

    /**
     * Test case: When the Unix mode is a combination of FILE_TYPE_FLAG and LINK_FLAG.
     * This should return true.
     */
    @Test
    public void testIsUnixSymlink_ReturnsTrueWhenModeHasLinkFlagAndOtherBits() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_link_extra");
        // Combining LINK_FLAG with other bits (e.g., permissions)
        int mode = UnixStat.LINK_FLAG | 0755;
        entry.setUnixMode(mode);

        assertTrue("isUnixSymlink should return true when mode contains LINK_FLAG bitwise", entry.isUnixSymlink());
    }

    /**
     * Test case: When the Unix mode is 0 (no flags set).
     * This should return false.
     */
    @Test
    public void testIsUnixSymlink_ReturnsFalseWhenModeIsZero() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_not_link");
        entry.setUnixMode(0);

        assertFalse("isUnixSymlink should return false when mode is 0", entry.isUnixSymlink());
    }

    /**
     * Test case: When the Unix mode has FILE_TYPE_FLAG set but is less than LINK_FLAG.
     * This should return false.
     */
    @Test
    public void testIsUnixSymlink_ReturnsFalseWhenModeIsBelowLinkFlag() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_regular_file");
        // Assuming typical UnixStat structure where LINK_FLAG is a specific value within FILE_TYPE_FLAG
        // We force a value that satisfies the bitmask but is numerically less than LINK_FLAG
        int lowMode = UnixStat.FILE_TYPE_FLAG & (UnixStat.LINK_FLAG - 1);
        entry.setUnixMode(lowMode);

        assertFalse("isUnixSymlink should return false when (mode & FILE_TYPE_FLAG) < LINK_FLAG", entry.isUnixSymlink());
    }

    /**
     * Test case: When the Unix mode is a regular file (not a link).
     * This should return false.
     */
    @Test
    public void testIsUnixSymlink_ReturnsFalseWhenModeIsRegularFile() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_file");
        // Using a standard regular file mode (e.g., 0100000 in octal for regular file)
        // In Commons Compress, regular file is usually 0x8000 or similar depending on UnixStat
        // We use a value that is definitely not a link.
        int regularFileMode = 0644; 
        entry.setUnixMode(regularFileMode);

        assertFalse("isUnixSymlink should return false for regular file mode", entry.isUnixSymlink());
    }
}
